package com.nkc;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(NpcKillCountConfig.GROUP)
public interface NpcKillCountConfig extends Config
{
	String GROUP = "npckillcounter";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show kill counts as an on-screen overlay in addition to the side panel"
	)
	default boolean showOverlay()
	{
		return true;
	}
}

package com.nkc;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class NpcKillCountOverlay extends OverlayPanel
{
	private final NpcKillCountPlugin plugin;
	private final NpcKillCountConfig config;

	@Inject
	private NpcKillCountOverlay(NpcKillCountPlugin plugin, NpcKillCountConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		Map<String, Integer> counts = plugin.getKillCounts();

		if (counts.isEmpty())
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("NPC Kill Counter")
			.color(Color.ORANGE)
			.build());

		for (Map.Entry<String, Integer> entry : counts.entrySet())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(entry.getKey())
				.right(String.valueOf(entry.getValue()))
				.build());
		}

		return super.render(graphics);
	}
}

package com.nkc;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class NpcKillCountPanel extends PluginPanel
{
	private final Consumer<String> onResetNpc;
	private final Runnable onResetAll;

	private final JPanel listPanel = new JPanel();

	public NpcKillCountPanel(Consumer<String> onResetNpc, Runnable onResetAll)
	{
		super(false);

		this.onResetNpc = onResetNpc;
		this.onResetAll = onResetAll;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

		JLabel title = new JLabel("NPC Kill Counter");
		title.setForeground(Color.WHITE);

		JButton resetAllButton = new JButton("Reset all");
		resetAllButton.addActionListener(e -> onResetAll.run());

		header.add(title, BorderLayout.WEST);
		header.add(resetAllButton, BorderLayout.EAST);

		listPanel.setLayout(new GridBagLayout());
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JScrollPane scrollPane = new JScrollPane(listPanel);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		add(header, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
	}

	public void rebuild(Map<String, Integer> counts)
	{
		listPanel.removeAll();

		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.insets = new Insets(0, 0, 4, 0);

		if (counts.isEmpty())
		{
			JLabel empty = new JLabel("No kills recorded yet.");
			empty.setForeground(Color.LIGHT_GRAY);
			listPanel.add(empty, c);
		}
		else
		{
			for (Map.Entry<String, Integer> entry : counts.entrySet())
			{
				listPanel.add(buildRow(entry.getKey(), entry.getValue()), c);
				c.gridy++;
			}
		}

		revalidate();
		repaint();
	}

	private JPanel buildRow(String name, int count)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

		JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(Color.WHITE);

		JLabel countLabel = new JLabel(String.valueOf(count));
		countLabel.setForeground(ColorScheme.BRAND_ORANGE);
		countLabel.setHorizontalAlignment(SwingConstants.CENTER);
		countLabel.setPreferredSize(new Dimension(36, 20));

		JButton resetButton = new JButton("x");
		resetButton.setToolTipText("Reset kills for " + name);
		resetButton.setMargin(new Insets(0, 4, 0, 4));
		resetButton.addActionListener(e -> onResetNpc.accept(name));

		JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		right.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		right.add(countLabel);
		right.add(resetButton);

		row.add(nameLabel, BorderLayout.CENTER);
		row.add(right, BorderLayout.EAST);

		return row;
	}
}

package com.nkc;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

/**
 * Tracks how many of each NPC type the local player has killed.
 * Kills are counted via NpcLootReceived: this event fires whenever the player
 * is credited with a kill (even on an empty drop), which avoids counting
 * kills made by other players.
 */
@Slf4j
@PluginDescriptor(
	name = "NPC Kill Counter",
	description = "Tracks kills per NPC type, with options to reset a single NPC or all of them",
	tags = {"npc", "kill", "counter", "tracker", "pvm"}
)
public class NpcKillCountPlugin extends Plugin
{
	private static final String CONFIG_GROUP = NpcKillCountConfig.GROUP;
	private static final String CONFIG_KEY = "counts";

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NpcKillCountOverlay overlay;

	@Inject
	private Gson gson;

	private NpcKillCountPanel panel;
	private NavigationButton navButton;

	private final Map<String, Integer> killCounts = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);

	@Provides
	NpcKillCountConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NpcKillCountConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadCounts();

		panel = new NpcKillCountPanel(this::resetNpc, this::resetAll);
		panel.rebuild(killCounts);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("NPC Kill Counter")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		String name = npc.getName();

		if (name == null)
		{
			return;
		}

		killCounts.merge(name, 1, Integer::sum);
		saveCounts();
		refreshPanel();
	}

	public Map<String, Integer> getKillCounts()
	{
		return Collections.unmodifiableMap(killCounts);
	}

	private void resetNpc(String name)
	{
		killCounts.remove(name);
		saveCounts();
		refreshPanel();
	}

	private void resetAll()
	{
		killCounts.clear();
		saveCounts();
		refreshPanel();
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		Map<String, Integer> snapshot = new TreeMap<>(killCounts);
		SwingUtilities.invokeLater(() -> panel.rebuild(snapshot));
	}

	private void loadCounts()
	{
		killCounts.clear();

		String json = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);

		if (json == null || json.isEmpty())
		{
			return;
		}

		Type type = new TypeToken<Map<String, Integer>>()
		{
		}.getType();

		try
		{
			Map<String, Integer> stored = gson.fromJson(json, type);

			if (stored != null)
			{
				killCounts.putAll(stored);
			}
		}
		catch (Exception e)
		{
			log.warn("Unable to read stored kill counts", e);
		}
	}

	private void saveCounts()
	{
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, gson.toJson(new LinkedHashMap<>(killCounts)));
	}
}
